import{_ as e,o as d,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const u=JSON.parse('{"title":"Keyboard shortcuts","description":"Keyboard shortcuts and drag modifiers for the Slides editor and slideshow.","frontmatter":{"title":"Keyboard shortcuts","description":"Keyboard shortcuts and drag modifiers for the Slides editor and slideshow.","type":"reference"},"headers":[],"relativePath":"slides/keyboard-shortcuts.md","filePath":"slides/keyboard-shortcuts.md"}'),a={name:"slides/keyboard-shortcuts.md"};function c(i,t,s,h,l,n){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>Keyboard shortcuts and drag modifiers for building and presenting a deck.</p><p>Mac shortcuts come first, then Windows and Linux. To see the list in the editor, press <code>⌘+/</code> / <code>Ctrl+/</code>.</p><h2 id="most-used" tabindex="-1">Most used <a class="header-anchor" href="#most-used" aria-label="Permalink to &quot;Most used&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Undo</td><td><code>⌘+Z</code> / <code>Ctrl+Z</code></td></tr><tr><td>Redo</td><td><code>⌘+Shift+Z</code> / <code>Ctrl+Shift+Z</code></td></tr><tr><td>Copy</td><td><code>⌘+C</code> / <code>Ctrl+C</code></td></tr><tr><td>Paste</td><td><code>⌘+V</code> / <code>Ctrl+V</code></td></tr><tr><td>Duplicate the selection, or the slide if nothing is selected</td><td><code>⌘+D</code> / <code>Ctrl+D</code></td></tr><tr><td>Delete the selection</td><td><code>Delete</code> or <code>Backspace</code></td></tr><tr><td>New slide after the current one, with the same layout</td><td><code>⌘+M</code> / <code>Ctrl+M</code></td></tr><tr><td>Present from the current slide</td><td><code>⌘+Enter</code> / <code>Ctrl+Enter</code></td></tr></tbody></table><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Previous or next slide</td><td><code>Page Up</code> / <code>Page Down</code></td></tr><tr><td>Previous or next slide, with the slide strip focused and nothing selected</td><td><code>↑</code> / <code>↓</code></td></tr></tbody></table><h2 id="selection" tabindex="-1">Selection <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;Selection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Select every object on the slide</td><td><code>⌘+A</code> / <code>Ctrl+A</code></td></tr><tr><td>Select the next or previous object</td><td><code>Tab</code> / <code>Shift+Tab</code></td></tr><tr><td>Start typing in the selected text box or shape</td><td><code>Enter</code> or <code>F2</code></td></tr><tr><td>Start typing and insert that character</td><td>Any letter, number, or symbol</td></tr><tr><td>Leave text editing, step out of a group, or clear the selection</td><td><code>Escape</code></td></tr></tbody></table><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Cut</td><td><code>⌘+X</code> / <code>Ctrl+X</code></td></tr><tr><td>Paste as plain text, while typing</td><td><code>⌘+Shift+V</code> / <code>Ctrl+Shift+V</code></td></tr><tr><td>Duplicate the current slide</td><td><code>⌘+Shift+D</code> / <code>Ctrl+Shift+D</code></td></tr><tr><td>Move the selection 1 px</td><td>Arrow keys</td></tr><tr><td>Move the selection 10 px</td><td><code>Shift+Arrow</code></td></tr></tbody></table><p>Outside a text box, <code>⌘+Shift+V</code> / <code>Ctrl+Shift+V</code> pastes the same as <code>⌘+V</code> / <code>Ctrl+V</code>.</p><h2 id="formatting" tabindex="-1">Formatting <a class="header-anchor" href="#formatting" aria-label="Permalink to &quot;Formatting&quot;">​</a></h2><p>These work while you type in a text box, shape, or table cell.</p><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Bold</td><td><code>⌘+B</code> / <code>Ctrl+B</code></td></tr><tr><td>Italic</td><td><code>⌘+I</code> / <code>Ctrl+I</code></td></tr><tr><td>Underline</td><td><code>⌘+U</code> / <code>Ctrl+U</code></td></tr><tr><td>Insert or edit a link</td><td><code>⌘+K</code> / <code>Ctrl+K</code></td></tr><tr><td>Clear formatting</td><td><code>⌘+\\</code> / <code>Ctrl+\\</code></td></tr><tr><td>Align left</td><td><code>⌘+Shift+L</code> / <code>Ctrl+Shift+L</code></td></tr><tr><td>Align center</td><td><code>⌘+Shift+E</code> / <code>Ctrl+Shift+E</code></td></tr><tr><td>Align right</td><td><code>⌘+Shift+R</code> / <code>Ctrl+Shift+R</code></td></tr><tr><td>Justify</td><td><code>⌘+Shift+J</code> / <code>Ctrl+Shift+J</code></td></tr><tr><td>Numbered list</td><td><code>⌘+Shift+7</code> / <code>Ctrl+Shift+7</code></td></tr><tr><td>Bulleted list</td><td><code>⌘+Shift+8</code> / <code>Ctrl+Shift+8</code></td></tr><tr><td>Increase indent</td><td><code>⌘+]</code> / <code>Ctrl+]</code></td></tr><tr><td>Decrease indent</td><td><code>⌘+[</code> / <code>Ctrl+[</code></td></tr></tbody></table><p>Strikethrough has no shortcut in slides.</p><h2 id="objects" tabindex="-1">Objects <a class="header-anchor" href="#objects" aria-label="Permalink to &quot;Objects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Bring forward</td><td><code>⌘+↑</code> / <code>Ctrl+↑</code></td></tr><tr><td>Send backward</td><td><code>⌘+↓</code> / <code>Ctrl+↓</code></td></tr><tr><td>Bring to front</td><td><code>⌘+Shift+↑</code> / <code>Ctrl+Shift+↑</code></td></tr><tr><td>Send to back</td><td><code>⌘+Shift+↓</code> / <code>Ctrl+Shift+↓</code></td></tr><tr><td>Group</td><td><code>⌘+Option+G</code> / <code>Ctrl+Alt+G</code></td></tr><tr><td>Ungroup</td><td><code>⌘+Shift+Option+G</code> / <code>Ctrl+Shift+Alt+G</code></td></tr><tr><td>Apply a crop</td><td><code>Enter</code></td></tr><tr><td>Cancel a crop</td><td><code>Escape</code></td></tr></tbody></table><p>The order shortcuts don&#39;t work while you type, so <code>⌘+↑</code> / <code>Ctrl+↑</code> still moves the cursor in text. While you crop an image, only <code>Enter</code> and <code>Escape</code> work.</p><h3 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h3><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Next cell, or add a row from the last cell</td><td><code>Tab</code></td></tr><tr><td>Previous cell</td><td><code>Shift+Tab</code></td></tr><tr><td>Next or previous cell, from the end or start of a cell&#39;s text</td><td><code>→</code> / <code>←</code></td></tr></tbody></table><h3 id="while-dragging" tabindex="-1">While dragging <a class="header-anchor" href="#while-dragging" aria-label="Permalink to &quot;While dragging&quot;">​</a></h3><table tabindex="0"><thead><tr><th>To do this</th><th>Hold</th></tr></thead><tbody><tr><td>Draw a square, circle, or other even shape</td><td><code>Shift</code> while drawing a shape</td></tr><tr><td>Snap a line to 15° steps</td><td><code>Shift</code> while drawing a line or dragging its end</td></tr><tr><td>Move along one axis only</td><td><code>Shift</code> while moving objects</td></tr><tr><td>Keep the proportions</td><td><code>Shift</code> while resizing</td></tr><tr><td>Snap rotation to 15° steps</td><td><code>Shift</code> while rotating</td></tr></tbody></table><h2 id="view" tabindex="-1">View <a class="header-anchor" href="#view" aria-label="Permalink to &quot;View&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Present from the current slide</td><td><code>⌘+Enter</code> / <code>Ctrl+Enter</code></td></tr><tr><td>Present from the beginning</td><td><code>⌘+Shift+Enter</code> / <code>Ctrl+Shift+Enter</code></td></tr><tr><td>Show keyboard shortcuts</td><td><code>⌘+/</code> / <code>Ctrl+/</code></td></tr></tbody></table><h3 id="during-a-slideshow" tabindex="-1">During a slideshow <a class="header-anchor" href="#during-a-slideshow" aria-label="Permalink to &quot;During a slideshow&quot;">​</a></h3><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Next step or slide</td><td><code>→</code>, <code>Space</code>, <code>Page Down</code>, or <code>N</code></td></tr><tr><td>Previous slide</td><td><code>←</code>, <code>Backspace</code>, <code>Page Up</code>, or <code>P</code></td></tr><tr><td>First slide</td><td><code>Home</code></td></tr><tr><td>Last slide</td><td><code>End</code></td></tr><tr><td>Leave the slideshow</td><td><code>Escape</code></td></tr></tbody></table><p>Editing shortcuts are off during a slideshow, so <code>⌘+Z</code> / <code>Ctrl+Z</code> can&#39;t change the deck. For mouse and touch controls, see <a href="/docs/slides/present.html#move-between-slides">Move between slides</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/slides/present.html">Present</a> for slideshow controls with a mouse or touch screen.</li><li><a href="/docs/slides/add-content.html">Add content</a> to format text and build tables.</li><li><a href="/docs/slides/style-and-arrange.html">Style and arrange</a> to crop images and arrange objects.</li></ul>',30)])])}const f=e(a,[["render",c]]);export{u as __pageData,f as default};
